    sexualOrientationList = ["", "BL", "GL", "BG", "无CP", "混合", "GB"],
    gradeList = ["", "全年龄", "辅导级", "限制级", "成人向"],
    typeList = ["", "原著向", "AU向"]

label = [];
// 性向
if (result.sexual_orientation != 1) {
  label.push(
    sexualOrientationList[result.sexual_orientation]
  );
}
// 发表类型
if (result.publish_type != 1) {
  label.push(publishTypeList[result.publish_type]);
}
// 分级
		gradeList[result.grade]?label.push(gradeList[result.grade]):label.push(result.grade);
// 类型
		typeList[result.type]?label.push(typeList[result.type]):label.push(result.type);

label.concat(result.label)

